package com.medipanda.controller;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.medipanda.model.Order;
import com.medipanda.model.User;
import com.medipanda.repository.OrderRepository;
import com.medipanda.repository.UserRepository;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.security.Principal;
import java.time.Duration;
import java.util.*;

@RestController @RequestMapping("/api/payments")
public class PaymentController {
 private final OrderRepository orders; private final UserRepository users; private final com.medipanda.service.NotificationService notifications; private final String storeId,storePassword,baseUrl; private final boolean sandbox; private final ObjectMapper mapper=new ObjectMapper();
 public PaymentController(OrderRepository o,UserRepository u,com.medipanda.service.NotificationService notifications,@Value("${app.integrations.sslcommerz-store-id:}") String storeId,@Value("${app.integrations.sslcommerz-store-password:}") String storePassword,@Value("${app.integrations.sslcommerz-sandbox:true}") boolean sandbox,@Value("${app.integrations.public-base-url:http://localhost:8081}") String baseUrl){orders=o;users=u;this.notifications=notifications;this.storeId=storeId;this.storePassword=storePassword;this.sandbox=sandbox;this.baseUrl=baseUrl;}
 @PostMapping("/{id}/pay") public Order pay(@PathVariable String id,@RequestBody Map<String,String> body,Principal p){Order o=orders.findById(id).orElseThrow();User u=users.findByEmailIgnoreCaseOrPhone(p.getName(),p.getName()).orElseThrow();if(!"ADMIN".equals(u.getRole())&&!p.getName().equalsIgnoreCase(o.getCustomerEmail()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Forbidden");String method=body.getOrDefault("method","COD").toUpperCase();if(!"COD".equals(method))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"For online payment, use the SSLCommerz checkout endpoint.");o.setPaymentMethod("COD");o.setPaymentStatus("PENDING");return orders.save(o);}
 @PostMapping("/{id}/sslcommerz/initiate") public Map<String,Object> initiate(@PathVariable String id,Principal p){Order o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found"));if(p==null||!p.getName().equalsIgnoreCase(o.getCustomerEmail()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the order owner can pay for this order.");if(storeId.isBlank()||storePassword.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"SSLCommerz is not configured. Set SSLCOMMERZ_STORE_ID and SSLCOMMERZ_STORE_PASSWORD.");if("PAID".equalsIgnoreCase(o.getPaymentStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Order is already paid.");try{double amount=Math.round((o.getTotal()+o.getDeliveryFee())*100.0)/100.0;if(amount<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Order amount must be greater than zero.");String tx="MP-"+o.getId()+"-"+UUID.randomUUID().toString().replace("-","").substring(0,12);String endpoint=sandbox?"https://sandbox.sslcommerz.com/gwprocess/v4/api.php":"https://securepay.sslcommerz.com/gwprocess/v4/api.php";Map<String,String> fields=new LinkedHashMap<>();fields.put("store_id",storeId);fields.put("store_passwd",storePassword);fields.put("total_amount",String.format(Locale.US,"%.2f",amount));fields.put("currency","BDT");fields.put("tran_id",tx);fields.put("success_url",baseUrl+"/api/payments/sslcommerz/success");fields.put("fail_url",baseUrl+"/api/payments/sslcommerz/fail");fields.put("cancel_url",baseUrl+"/api/payments/sslcommerz/cancel");fields.put("ipn_url",baseUrl+"/api/payments/sslcommerz/ipn");fields.put("cus_name",safe(o.getCustomerName(),"MediPanda Customer"));fields.put("cus_email",safe(o.getCustomerEmail(),"customer@example.com"));fields.put("cus_add1",safe(o.getDeliveryAddress(),"Bangladesh"));fields.put("cus_city","Dhaka");fields.put("cus_country","Bangladesh");fields.put("cus_phone",users.findByEmailIgnoreCaseOrPhone(p.getName(),p.getName()).map(User::getPhone).filter(x->x!=null&&!x.isBlank()).orElse("01700000000"));fields.put("shipping_method","NO");fields.put("product_name","MediPanda order "+o.getId());fields.put("product_category","Medicine");fields.put("product_profile","general");fields.put("num_of_item",Integer.toString(Math.max(1,o.getItems()==null?1:o.getItems().size())));String form=fields.entrySet().stream().map(e->enc(e.getKey())+"="+enc(e.getValue())).reduce((a,b)->a+"&"+b).orElse("");HttpRequest req=HttpRequest.newBuilder(URI.create(endpoint)).timeout(Duration.ofSeconds(20)).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(form)).build();HttpResponse<String> res=HttpClient.newHttpClient().send(req,HttpResponse.BodyHandlers.ofString());JsonNode json=mapper.readTree(res.body());String url=json.path("GatewayPageURL").asText("");if(res.statusCode()!=200||url.isBlank())throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"SSLCommerz could not initialize checkout. Verify merchant credentials and required customer data.");o.setPaymentMethod("SSLCOMMERZ");o.setPaymentStatus("INITIATED");orders.save(o);return Map.of("success",true,"transactionId",tx,"gatewayUrl",url,"sandbox",sandbox);}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Could not connect to SSLCommerz.");}}
 @PostMapping("/sslcommerz/success") public Map<String,Object> success(@RequestParam Map<String,String> params){return validateAndUpdate(params,"SUCCESS");}
 @PostMapping("/sslcommerz/ipn") public Map<String,Object> ipn(@RequestParam Map<String,String> params){return validateAndUpdate(params,"IPN");}
 @PostMapping("/sslcommerz/fail") public Map<String,Object> fail(@RequestParam Map<String,String> params){markFailed(params);return Map.of("success",false,"message","Payment was not completed. You may retry from your order page.");}
 @PostMapping("/sslcommerz/cancel") public Map<String,Object> cancel(@RequestParam Map<String,String> params){markFailed(params);return Map.of("success",false,"message","Payment was cancelled.");}
 private Map<String,Object> validateAndUpdate(Map<String,String> p,String source){String valId=p.get("val_id");String tranId=p.get("tran_id");if(valId==null||tranId==null||storeId.isBlank()||storePassword.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Missing payment validation data.");try{String endpoint=(sandbox?"https://sandbox.sslcommerz.com/validator/api/validationserverAPI.php":"https://securepay.sslcommerz.com/validator/api/validationserverAPI.php")+"?val_id="+enc(valId)+"&store_id="+enc(storeId)+"&store_passwd="+enc(storePassword)+"&format=json";HttpRequest req=HttpRequest.newBuilder(URI.create(endpoint)).timeout(Duration.ofSeconds(15)).GET().build();HttpResponse<String> res=HttpClient.newHttpClient().send(req,HttpResponse.BodyHandlers.ofString());JsonNode j=mapper.readTree(res.body());if(res.statusCode()!=200||!("VALID".equalsIgnoreCase(j.path("status").asText())||"VALIDATED".equalsIgnoreCase(j.path("status").asText()))||!tranId.equals(j.path("tran_id").asText()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Payment could not be validated.");String orderId=extractOrderId(tranId);Order o=orders.findById(orderId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found."));double expected=Math.round((o.getTotal()+o.getDeliveryFee())*100.0)/100.0;double paid=j.path("amount").asDouble(-1);if(Math.abs(paid-expected)>0.01||!"BDT".equalsIgnoreCase(j.path("currency").asText()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Payment amount or currency mismatch.");o.setPaymentMethod("SSLCOMMERZ");boolean first=!"PAID".equalsIgnoreCase(o.getPaymentStatus());o.setPaymentStatus("PAID");orders.save(o);if(first)notifications.notifyCustomer(o,com.medipanda.service.NotificationService.OrderEvent.PAID);return Map.of("success",true,"message","Payment verified","orderId",o.getId(),"paymentStatus","PAID");}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Payment validation service unavailable.");}}
 private void markFailed(Map<String,String> p){String id=extractOrderId(p.get("tran_id"));if(id!=null)orders.findById(id).ifPresent(o->{if(!"PAID".equalsIgnoreCase(o.getPaymentStatus())){o.setPaymentStatus("FAILED");orders.save(o);}});}
 private String extractOrderId(String tx){if(tx==null||!tx.startsWith("MP-"))return null;int end=tx.lastIndexOf('-');return end>3?tx.substring(3,end):null;}
 private String enc(String s){return URLEncoder.encode(s==null?"":s,StandardCharsets.UTF_8);} private String safe(String s,String d){return s==null||s.isBlank()?d:s;}
}
